function drawLifeIcons(){let el=$('#hearts');el.setAttribute('aria-label',player.hp+' de '+player.max+' corações');if(!heartIconUrl){el.textContent='♥ '.repeat(Math.max(0,player.hp))+'♡ '.repeat(Math.max(0,player.max-player.hp));return}el.innerHTML=Array.from({length:player.max},(_,i)=>'<img src="'+heartIconUrl+'" alt="" width="18" height="16" style="display:inline-block;vertical-align:middle;image-rendering:pixelated;margin-right:2px;'+(i>=player.hp?'filter:brightness(0);':'')+'">').join('')}

