function hitEnemy(e,damage=1){if(player.dead||!e.alive)return;e.hp-=damage;if(hero===0)burst(e.x+e.w/2,e.y+e.h/2,heroes[hero].color,8);if(damage===1){player.special=Math.min(specialLimit(),player.special+1);specialCharge=player.special;if(player.special===specialLimit())say('ESPECIAL PRONTO',850)}if(e.hp<=0){e.alive=false;addScore(10);sound(210,.1,'triangle')}updateHud()}
