function attackDirection(){if(keys.arrowup)return{x:0,y:-1};if(keys.arrowdown)return{x:0,y:1};if(keys.arrowleft)return{x:-1,y:0};if(keys.arrowright)return{x:1,y:0};if(Math.abs(player.vx||0)>35)return{x:Math.sign(player.vx),y:0};return{x:player.face||1,y:0}}function queueAreaAttackVfx(special,targets,heroIndex=hero){let direction=attackDirection(),face=direction.x||player.face||1,offset=heroIndex===2?34:24,originX=player.x+player.w/2+direction.x*offset,originY=direction.y<0?player.y-offset:direction.y>0?player.y+player.h+offset:player.y+26;attackVfx.push({hero:heroIndex,special,phase:'cast',t:0,originX,originY,x:originX,y:originY,face,direction,followPlayer:true,socketOffset:offset,range:heroIndex===2?(special?worldWidth:600):(special?330:150),targets:targets.map(p=>({...p}))})}
