function updateAttackVfx(dt){let next=[];for(const v of attackVfx){v.t+=dt;if(v.phase==='cast'){if(v.followPlayer){let direction=v.direction||{x:v.face||1,y:0};v.originX=direction.x?player.x+player.w/2+direction.x*v.socketOffset:player.x+player.w/2;v.originY=direction.y<0?player.y-v.socketOffset:direction.y>0?player.y+player.h+v.socketOffset:player.y+(v.shot?24:26);v.x=v.originX;v.y=v.originY;if(v.shot){let d=v.shot.direction,s=v.shot;s.x=d.x>0?player.x+player.w:d.x<0?player.x-s.w:player.x+player.w/2-s.w/2;s.y=d.y<0?player.y-s.h:d.y>0?player.y+player.h:player.y+24}}let castDuration=(v.special?12:8)/24;if(v.t<castDuration){next.push(v);continue}if(v.shot){if(v.shot.visualHits.length){for(const hit of v.shot.visualHits){let target={x:hit.x,y:hit.y};next.push({...v,shot:null,phase:'projectile',t:0,x:v.originX,y:v.originY,target,face:Math.sign(target.x-v.originX)||v.face})}}else if(v.shot.life>0){shots.push(v.shot);next.push({...v,phase:'projectile',t:0})}continue}let targets=v.targets.length?v.targets:[{x:v.originX+v.face*v.range,y:v.originY,miss:true}];for(const target of targets)next.push({...v,phase:'projectile',t:0,x:v.originX,y:v.originY,target,face:Math.sign(target.x-v.originX)||v.face});continue}if(v.phase==='projectile'){if(v.shot){if(v.shot.visualHits.length){for(const hit of v.shot.visualHits)next.push({...v,phase:'impact',t:0,x:hit.x,y:hit.y})}else if(v.shot.life>0){v.x=v.shot.x+v.shot.w/2;v.y=v.shot.y+v.shot.h/2;next.push(v)}continue}if((v.hero===1||v.hero===2)&&v.target.entity){let entity=v.target.entity;if(v.target.boss?entity.hp<=0:!entity.alive)continue;v.target.x=entity.x+entity.w/2;v.target.y=entity.y+entity.h/2}let dx=v.target.x-v.originX,dy=v.target.y-v.originY,distance=Math.hypot(dx,dy);if(distance>0)v.direction={x:dx/distance,y:dy/distance};let flight=Math.max(.06,distance/620),progress=Math.min(1,v.t/flight);v.x=v.originX+dx*progress;v.y=v.originY+dy*progress;if(progress>=1){if((v.hero===1||v.hero===2)&&v.target.entity){if(v.target.boss)hitBoss(v.target.damage,v.target.charge);else hitEnemy(v.target.entity,v.target.damage)}if(!v.target.miss)next.push({...v,phase:'impact',t:0,x:v.target.x,y:v.target.y});continue}next.push(v);continue}let frames=v.special?12:8;if(v.t<frames/24)next.push(v)}attackVfx=next}
function attack(special=false){if(hero===3){fireElli(special);return;}if(special){if(player.special<specialLimit())return;player.special=0;specialCharge=0;player.attack=.5;player.specialAnim=.5;player.anim='special';player.animClock=0;let col=heroes[hero].color;if(hero===0)burst(player.x+player.w/2,player.y+player.h/2,col,34);sound(180,.34,'sawtooth');let specialArea={x:player.x-310,y:player.y-120,w:620,h:280};if(hero===0||hero===1)clearEnemyProjectiles(specialArea);let specialDamage=hero===0?20:hero===1?20:3;let attackTargets=[];if(hero===1){for(const e of enemies){if(e.alive&&Math.abs(e.x-player.x)<330)attackTargets.push({x:e.x+e.w/2,y:e.y+e.h/2,entity:e,damage:20})}if(boss&&boss.hp>0&&Math.abs(boss.x-player.x)<490)attackTargets.push({x:boss.x+boss.w/2,y:boss.y+boss.h/2,entity:boss,boss:true,damage:20,charge:false});queueAreaAttackVfx(true,attackTargets,hero);updateHud();return}if(hero===2){for(const e of enemies){if(e.alive)attackTargets.push({x:e.x+e.w/2,y:e.y+e.h/2,entity:e,damage:3})}if(boss&&boss.hp>0)attackTargets.push({x:boss.x+boss.w/2,y:boss.y+boss.h/2,entity:boss,boss:true,damage:10,charge:false});queueAreaAttackVfx(true,attackTargets,hero);updateHud();return}if(boss){if(Math.abs(boss.x-player.x)<490){if(hero===1||hero===2)attackTargets.push({x:boss.x+boss.w/2,y:boss.y+boss.h/2,...(hero===2?{entity:boss,boss:true,damage:10,charge:false}:{})});if(hero!==2)hitBoss(specialDamage)}}else enemies.forEach(e=>{if(e.alive&&Math.abs(e.x-player.x)<330){if(hero===1||hero===2)attackTargets.push({x:e.x+e.w/2,y:e.y+e.h/2,...(hero===2?{entity:e,damage:specialDamage}:{})});if(hero!==2)hitEnemy(e,specialDamage)}});if(hero===1||hero===2)queueAreaAttackVfx(true,attackTargets,hero);else shots.push({...specialArea,t:.4,special:true,color:col});updateHud();return}
if(player.attack>0)return;player.attack=.5;player.anim='attack';player.animClock=0;sound(hero===1?620:hero===2?400:300,.06);if(hero===1){let direction=attackDirection(),vertical=direction.y!==0,w=vertical?13:24,h=vertical?24:13,x=direction.x>0?player.x+player.w:direction.x<0?player.x-w:player.x+player.w/2-w/2,y=direction.y<0?player.y-h:direction.y>0?player.y+player.h:player.y+24;let shot={x,y,w,h,vx:direction.x*590,vy:direction.y*590,direction,life:1.15,damage:1,color:heroes[hero].color,from:'player',vfxType:'vazNormal',visualHits:[]};queueVazShotVfx(shot);return}let reach=hero===0?115:hero===2?600:75;let box={x:player.face>0?player.x+player.w:player.x-reach,y:player.y+(player.crouch?32:8),w:reach,h:player.crouch?24:player.h-14};if(hero===0)clearEnemyProjectiles(box);let attackTargets=[];if(boss&&rect(box,boss)){if(hero===2)attackTargets.push({x:boss.x+boss.w/2,y:boss.y+boss.h/2,entity:boss,boss:true,damage:1,charge:true});else hitBoss(1,true)}enemies.forEach(e=>{if(e.alive&&rect(box,e)){if(hero===2)attackTargets.push({x:e.x+e.w/2,y:e.y+e.h/2,entity:e,damage:1});else hitEnemy(e)}});if(hero===2)queueAreaAttackVfx(false,attackTargets,hero);else if(hero!==0)shots.push({x:box.x,y:box.y+box.h/2-5,w:box.w,h:10,life:.13,t:.13,special:false,color:heroes[hero].color})}
const rect=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
