function drawPlayer(p,h,worldAccent,scale=1){if(hero===3){if(heroLocked()&&screen!=='game')return;if(!drawElli(p,scale))drawSecretHero(p,scale);return;}if(hero===2&&drawRitt(p,scale))return;if(hero===1&&drawVazAction(p,scale))return;if(hero===0&&p.anim==='attack'&&drawBuenoNormalAttack(p,scale))return;ctx.save();ctx.translate(p.x+p.w/2,p.y+p.h);let anim=(hero===2?rittAnimations:hero===1?vazAnimations:animations)[p.anim]||animations.idle,frame=Math.floor((p.animClock||0)*anim.fps)%anim.count,sx=anim.x+frame*anim.w+5,sy=anim.y+5,sw=anim.w-10,sh=anim.h-10,dw=anim.row>=5?84:78,dh=anim.row>=5?72:82;if(p.crouch&&p.ground){dh*=.82;dw*=1.04}let flipLeftAttack=p.face<0&&(p.anim==='idle'||p.anim==='attack'||p.anim==='special'),flipRittWalk=hero===2&&p.anim==='walkRight';ctx.scale(flipLeftAttack||flipRittWalk?-scale:scale,scale);if(p.invuln>0&&Math.floor(p.invuln*15)%2)ctx.globalAlpha=.4;let sheet=hero===2?rittSpriteSheet:hero===1?vazSpriteSheet:buenoSpriteSheet;if(sheet.complete&&sheet.naturalWidth)ctx.drawImage(sheet,sx,sy,sw,sh,-dw/2,-dh,dw,dh);else{ctx.fillStyle=h.color;ctx.beginPath();ctx.arc(0,-dh*.65,dw*.22,0,Math.PI*2);ctx.fill();roundRect(-dw*.22,-dh*.48,dw*.44,dh*.43,7,h.dark,h.color)}ctx.restore()}
